arTodasLeidas((int)$_SESSION['usuario_id']);","        if (!$this->verificarLecturaSegura()) { exit; }\n        $modelo = new ConvocatoriaNotificacionModel();\n        $ok = $modelo->marcarTodasLeidas((int)$_SESSION['usuario_id']);"],["    private function esMarketingAutenticado()\n    {","    /** Lectura de alertas: sólo POST autenticado y con CSRF de la sesión. */\n    private function verificarLecturaSegura(): bool\n    {\n        if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') {\n            http_response_code(405);\n            echo json_encode(['ok' => false, 'mensaje' => 'Método no permitido.'], JSON_UNESCAPED_UNICODE);\n            return false;\n        }\n        $token = (string)($_SESSION['csrf_token'] ?? '');\n        if ($token === '' || !hash_equals($token, (string)($_POST['csrf_token'] ?? ''))) {\n            http_response_code(403);\n            echo json_encode(['ok' => false, 'mensaje' => 'La sesión de lectura caducó. Recarga el CRM.'], JSON_UNESCAPED_UNICODE);\n            return false;\n        }\n        return true;\n    }\n\n    private function esMarketingAutenticado()\n    {"]]},{"path":"app/views/layout/topbar.php","patches":[["\n                    <div class=\"dropdown-menu dropdown-menu-end topbar-reminder-menu convocatoria-notification-menu\">\n                        <div class=\"topbar-reminder-header convocatoria-notification-header\">\n                            <div>\n                                <strong>Alertas de convocatorias</strong>\n                                <span>Activaciones automáticas y vencimientos próximos.</span>\n                            </div>\n                            <button\n                                type=\"button\"\n                                class=\"convocatoria-notification-read-all\"","\n                    <div class=\"dropdown-menu dropdown-menu-end topbar-reminder-menu convocatoria-notification-menu\">\n                        <div class=\"topbar-reminder-header convocatoria-n