mientos y pendientes telefónicos.</span>\n                            <?php endif; ?>\n                            </div>\n                            <?php if ($puedeUsarTelefoniaTopbar && !$esMarketingTopbar &&\n                                    ($puedeRecibirTelefoniaTopbar || ((int)($_SESSION['rol_id']??0)===3&&tienePermiso('telefonia.salientes')))): ?>\n                                <button type=\"button\" class=\"convocatoria-notification-read-all\"\n                                    data-phone-notification-read-all\n                                    data-phone-notification-read-all-url=\"<?= BASE_URL ?>prueba_telefonia/api/leer_todas_notificaciones_llamada.php\"\n                                    title=\"Marcar avisos telefónicos como leídos; las tareas pendientes permanecen\">\n                                    Marcar llamadas leídas\n                                </button>\n                            <?php endif; ?>\n                        </div>\n\n                        <div data-reminder-content aria-live=\"polite\" aria-busy=\"true\">"],["if($puedeUsarTelefoniaTopbar&&($puedeRecibirTelefoniaTopbar||((int)($_SESSION['rol_id']??0)===3&&tienePermiso('telefonia.salientes')))&&empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));","if(($esMarketingTopbar||($puedeUsarTelefoniaTopbar&&($puedeRecibirTelefoniaTopbar||((int)($_SESSION['rol_id']??0)===3&&tienePermiso('telefonia.salientes')))))&&empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));"],["                    data-read-all-endpoint=\"<?= BASE_URL ?>index.php?controller=convocatoriaNotificacion&action=marcarTodasLeidas\">","                    data-read-all-endpoint=\"<?= BASE_URL ?>index.php?controller=convocatoriaNotificacion&action=marcarTodasLeidas\"\n                    data-csrf-token=\"<?= htmlspecialchars((string)($_SESSION['csrf_token']??''),ENT_QUOTES,'UTF-8') ?>\">"]]},{"path":"public/javascript/telefonia_notificaciones.js","patches":[["/* Las perdidas usan las campanas existentes y se leen sólo por su propietario. */\ndocument.addEventListener('DOMContentLoaded',()=>{\n const root=document.querySelector('[data-phone-notification-read]');if(!root)return;\n document.addEventListener('click',async event=>{\n  const item=event.target.closest('[data-telefonia-id]');if(!item||event.target.closest('.convocatoria-activation-toast-close'))return;\n  event.preventDefault();event.stopImmediatePropagation();\n  const destination=new URL(item.getAttribute('href'),window.location.href);","/* Las perdidas usan las campanas existentes y se leen sólo por su propietario. */\ndocument.addEventListener('DOMContentLoaded',()=>{\n const root=document.querySelector('[data-phone-notification-read]');if(!root)return;\n const markAll=document.querySelector('[data-phone-notification-read-all]');\n if(markAll)markAll.addEventListener('click',async event=>{\n  event.preventDefault();event.stopPropagation();\n  if(markAll.disabled)return;\n  const url=markAll.dataset.phoneNotificationReadAllUrl;\n  if(!url)return;\n  markAll.disabled=true;\n  try{\n   const res=await fetch(url,{method:'POST',credentials:'same-origin',\n    body:new URLSearchParams({csrf_token:root.dataset.phoneNotificationCsrf})});\n   const data=await res.json();\n   if(!res.ok||!data.ok)throw Error('No fue posible marcar los avisos telefónicos como leídos.');\n   window.dispatchEvent(new Event('impe:phone-notices-refresh'));\n  }catch(error){window.IMPE_TELEPHONY_NOTIFY?.(error.message,true);}\n  finally{markAll.disabled=false;}\n });\n document.addEventListener('click',async event=>{\n  const item=event.target.closest('[data-telefonia-id]');if(!item||event.target.closest('.convocatoria-activation-toast-close'))return;\n  event.preventDefault();event.stopImmediatePropagation();\n  const destination=new URL(item.getAttribute('href'),window.location.href);"]]},{"path":"public/javascript/recordatorios.js","patches":[["                    const 