ntent-Type': 'application/x-www-form-urlencoded;charset=UTF-8',\n                    'X-Requested-With': 'fetch'\n                },\n                body: body.toString()\n            });\n            const data = await response.json();\n            if (!response.ok || !data.ok) throw new Error('No fue posible confirmar la lectura.');\n            return true;\n        } catch (error) {\n            window.IMPE_TELEPHONY_NOTIFY?.(error.message, true);\n            return false;\n        }"],["            await markAsRead(item.id);\n            window.location.href = toast.href;","            if (await markAsRead(item.id)) window.location.href = toast.href;"],["        await markAsRead(item.dataset.convocatoriaNotificationId || '0');\n        window.location.href = destination;","        if (await markAsRead(item.dataset.convocatoriaNotificationId || '0')) {\n            window.location.href = destination;\n        }"],["            try {\n                await fetch(readAllEndpoint, {\n                    method: 'POST',\n                    headers: { 'X-Requested-With': 'fetch' }\n                });\n                await load();\n            } catch (error) {\n                // Mantener la campana operativa aunque el marcado falle.\n            }","            if (markAll.disabled) return;\n            markAll.disabled = true;\n            try {\n                const response = await fetch(readAllEndpoint, {\n                    method: 'POST',\n                    credentials: 'same-origin',\n                    headers: { 'X-Requested-With': 'fetch' },\n                    body: new URLSearchParams({ csrf_token: csrfToken })\n                });\n                const data = await response.json();\n                if (!response.ok || !data.ok) throw new Error('No fue posible confirmar la lectura.');\n                await load();\n            } catch (error) {\n                window.IMPE_TELEPHONY_NOTIFY?.(error.message, true);\n            } finally {\n                markAll.disabled = false;\n            }"]]},{"path":"app/controllers/ReminderController.php","patches":[["        $recordatorios = array_slice(\n            $this->ordenarRecordatorios($recordatorios),\n            0,\n            12\n        );","        // La campana conserva todas las obligaciones telefónicas actuales,\n        // además de los 12 recordatorios habituales de los demás módulos.\n        $ordenados = $this->ordenarRecordatorios($recordatorios);\n        $telefoniaActiva = array_values(array_filter($ordenados,\n            static fn($item) => (int)($item['telefonia_id'] ?? 0) > 0 && !empty($item['pendiente_operativo'])));\n        $otros = array_values(array_filter($ordenados,\n            static fn($item) => (int)($item['telefonia_id'] ?? 0) <= 0 || empty($item['pendiente_operativo'])));\n        $recordatorios = array_merge($telefoniaActiva, array_slice($otros, 0, 12));"]]}],"newFile":{"path":"prueba_telefonia/api/leer_todas_notificaciones_llamada.php","content":"<?php\n/** Marcar avisos telefónicos como leídos; sin cerrar tareas de negocio. */\ndeclare(strict_types=1);\nsession_start();\nheader('Content-Type: application/json; charset=utf-8');\nheader('Cache-Control: private, no-store');\nrequire_once dirname(__DIR__,2).'/app/helpers/PermissionHelper.php';\nrequire_once dirname(__DIR__,2).'/app/services/TelefoniaNotificacionService.php';\n$uid=(int)($_SESSION['usuario_id']??0);\n$allowed=tienePermiso('telefonia.usar') &&\n    (tienePermiso('telefonia.recibir') ||\n    ((int)($_SESSION['rol_id']??0)===3 && tienePermiso('telefonia.salientes')));\nif(!$uid||!$allowed){http_response_code(403);echo '{\"ok\":false}';exit;}\nif(($_SERVER['REQUEST_METHOD']??'')!=='POST'){http_response_code(405);echo '{\"ok\":false}';exit;}\nif(empty($_SESSION['csrf_token']) ||\n    !hash_equals((string)$_SESSION['csrf_token'],(string)($_POST['csrf_token']??''))){\n    http_response_code(403);echo '{\"ok\":false}';exit;\n}\nsession_write_close();\ntry{\n    (new TelefoniaNotificacionService())->leerTodas($uid);\n    echo '{\"ok\":true}';\n}catch(Throwable $e){\n    error_log('[telefono_notificaciones_leer_todas] '.get_class($e));\n    http_response_code(500);echo '{\"ok\":false}';\n}\n"},"hostingerVariants":{"app/services/TelefoniaNotificacionService.php":{"origen":"Hostinger fundacionrededumex.org, servicio de 97 lineas, rutas Recepcion/Seguimiento preservadas","source_sha":"f7719e9e3b75c5fd46784609d73736a8f485d2d359b61d34210e349172eca98f","updated_sha":"POR_CALCULAR_CI","patches":[["require_once __DIR__.'/TelefoniaDisponibilidadService.php';\nfinal class TelefoniaNotificacionService\n{\n    private mysqli $db;\n    public function __construct(?mysqli $db=null){\n        $this->db=$db??(new Database())->connect();\n        $this->db->query(\"CREATE TABLE IF NOT EXISTS telefonia_notificaciones (\n            id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,","require_once __DIR__.'/TelefoniaDisponibilidadService.php';\nfinal class TelefoniaNotificacionService\n{\n    private mysqli $db;\n    /** Claves de obligaciones verificadas en esta consulta; leer no las resuelve. */\n    private array $operativasActuales=[];\n    private static function esOperativa(string $llave): bool {\n        return str_starts_with($llave,'devolucion:') || str_starts_with($llave,'transferencia:');\n    }\n    public function __construct(?mysqli $db=null){\n        $this->db=$db??(new Database())->connect();\n        $this->db->query(\"CREATE TABLE IF NOT EXISTS telefonia_notificaciones (\n            id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT NOT NULL,"],["        $s=$this->db->prepare('INSERT IGNORE INTO telefonia_notificaciones (usuario_id,extension,llave,numero,titulo,mensaje,created_at) VALUES (?,?,?,?,?,?,?)');\n        $s->bind_param('issssss',$user,$ext,$key,$number,$title,$message,$date);$s->execute();$s->close();\n    }\n    public function sincronizar(int $user,bool $recepcion): void {\n        if($this->esVentas($user)){require_once __DIR__.'/TelefoniaNotificacionVentasService.php';(new TelefoniaNotificacionVentasService($this->db))->pendientes($user);return;}\n        $ext=$this->extension($user);if($ext==='')return;\n        foreach((new TelefoniaDisponibilidadService($this->db))->devoluciones($user) as $task){\n            $date=(new DateTimeImmutable($task['updated_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('America/Mexico_City'))->format('Y-m-d H:i:s');\n            $this->agregar($user,$ext,'devolucion:'.$task['id'].':'.$task['version'],$task['telefono'],$date,'Llamada por devolver',$task['contacto'].' · Recepción dejó sus datos y el motivo.');\n        }\n        $s=$this->db->prepare(\"UPDATE telefonia_notificaciones n JOIN telefonia_disponibilidad d ON n.llave=CONCAT('devolucion:',d.id,':',d.version) SET n.leida=1 WHERE n.usuario_id=? AND n.extension=? AND d.destino_usuario=n.usuario_id AND d.devolucion='ATENDIDA'\");","        $s=$this->db->prepare('INSERT IGNORE INTO telefonia_notificaciones (usuario_id,extension,llave,numero,titulo,mensaje,created_at) VALUES (?,?,?,?,?,?,?)');\n        $s->bind_param('issssss',$user,$ext,$key,$number,$title,$message,$date);$s->execute();$s->close();\n    }\n    public function sincronizar(int $user,bool $recepcion): void {\n        $this->operativasActuales=[];\n        if($this->esVentas($user)){require_once __DIR__.'/TelefoniaNotificacionVentasService.php';(new TelefoniaNotificacionVentasService($this->db))->pendientes($user);return;}\n        $ext=$this->extension($user);if($ext==='')return;\n        foreach((new TelefoniaDisponibilidadService($this->db))->devoluciones($user) as $task){\n            if(($task['devolucion']??'')!=='PENDIENTE')continue;\n            $this->operativasActuales['devolucion:'.$task['id'].':'.$task['version']]=true;\n            $date=(new DateTimeImmutable($task['updated_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('America/Mexico_City'))->format('Y-m-d H:i:s');\n            $this->agregar($user,$ext,'devolucion:'.$task['id'].':'.$task['version'],$task['telefono'],$date,'Llamada por devolver',$task['contacto'].' · Recepción dejó sus datos y el motivo.');\n        }\n        $s=$this->db->prepare(\"UPDATE telefonia_notificaciones n JOIN telefonia_disponibilidad d ON n.llave=CONCAT('devolucion:',d.id,':',d.version) SET n.leida=1 WHERE n.usuario_id=? AND n.extension=? AND d.destino_usuario=n.usuario_id AND d.devolucion='ATENDIDA'\");"],["        try{\n        foreach((new TelefoniaTransferenciaOperacionService($this->db))->delUsuario($user) as $op){\n            $direct=$op['modo']==='DIRECTA';$source=(int)$op['origen_usuario']===$user;\n            if($direct){\n                if(!in_array($op['estado'],['SIN_RESPUESTA','SIN_CONFIRMAR'],true)){\n                    if(!empty($op['destino_atendida'])){$clear=$this->db->prepare(\"UPDATE telefonia_notificaciones SET leida=1 WHERE usuario_id=? AND extension=? AND llave IN (?,?)\");$k1='transferencia:'.$op['id'].':'.$op['intento'].':SIN_RESPUESTA';$k2='transferencia:'.$op['id'].':'.$op['intento'].':SIN_CONFIRMAR';$clear->bind_param('isss',$user,$ext,$k1,$k2);$clear->execute();$clear->close();}continue;\n                }\n                $date=(new DateTimeImmutable($op['created_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('America/Mexico_City'))->format('Y-m-d H:i:s');\n                $confirmed=$op['estado']==='SIN_RESPUESTA';\n                // Una devolución asignada ya tiene su aviso propio con acceso a Llamar.\n                if(!$source&&$confirmed){$q=$this->db->prepare(\"SELECT id FROM telefonia_disponibilidad WHERE origen_usuario=? AND destino_usuario=? AND referencia=? AND devolucion IN ('PENDIENTE','ATENDIDA')\");$q->bind_param('iis',$op['origen_usuario'],$user,$op['referencia']);$q->execute();$task=$q->get_result()->fetch_assoc();$q->close();if($task)continue;}\n                $message=$confirmed?($source?'La extensión '.$op['de