def fail(why):
    sys.stderr.write('CONFLICTO: '+why+'\n');sys.exit(2)
if len(sys.argv)<2 or sys.argv[1] not in ('--check','--apply','--restore'):
    sys.stderr.write('Uso: IMPE_CRM_PUBLIC=... bash publicador --check|--apply|--restore [respaldo]\n');sys.exit(1)
action=sys.argv[1];env=os.environ.get('IMPE_CRM_PUBLIC','')
if not env:fail('Falta IMPE_CRM_PUBLIC')
site=Path(env).resolve()
if not (site/'index.php').is_file():fail('No se reconocio public_html')
backups=Path(os.environ.get('IMPE_CRM_BACKUPS',str(Path.home()/'impe-telefonia-notificaciones-backups'))).resolve()
if backups==site or backups in site.parents or site in backups.parents:
    fail('Respaldo debe quedar fuera de public_html')
files=[x['path'] for x in SPEC['changes']]+[SPEC['newFile']['path']]
if len(files)!=len(SPEC['changes'])+1 or len(set(files))!=len(files):fail('Manifiesto no valido')
def sha(value):return hashlib.sha256(value).hexdigest()
def get(name,needed=True):
    p=site/name
    if p.is_symlink() or site not in p.resolve().parents:fail('Ruta insegura: '+name)
    if needed and not p.is_file():fail('Falta archivo: '+name)
    if not needed and p.exists() and not p.is_file():fail('Ruta incompatible: '+name)
    return p
def replace(path,contents,mode):
    fd,tmp=tempfile.mkstemp(prefix='.impe-notificaciones-',dir=str(path.parent))
    try:
        os.fchmod(fd,mode)
        with os.fdopen(fd,'wb') as f:f.write(contents);f.flush();os.fsync(f.fileno())
        os.replace(tmp,str(path))
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
def lint(name,contents):
    exe='php' if name.endswith('.php') else ('node' if name.endswith('.js') else None)
    if exe is None:return
    if not shutil.which(exe):
        if exe=='php':fail('Se requiere PHP para comprobar sintaxis')
        print('AVISO: node no disponible; JS debe validarse en CI.')
        return
    suffix='.php' if exe=='php' else '.js'
    fd,p=tempfile.mkstemp(suffix=suffix)
    try:
        with os.fdopen(fd,'wb') as f:f.write(contents)
        proc=subprocess.run([exe,'-l' if exe=='php' else '--check',p],
            stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        if proc.returncode:fail('Error de sintaxis en '+name+': '+(proc.stdout+proc.stderr).decode('utf8','replace')[-600:])
    finally:
        if os.path.exists(p):os.unlink(p)
if action=='--restore':
    if len(sys.argv)!=3:fail('Indica el respaldo exacto de esta entrega')
    backup=Path(sys.argv[2]).resolve()
    if backups not in backup.parents or backup.is_symlink():fail('Ruta de respaldo no autorizada')
    mf=backup/'manifest.json'
    if not mf.is_file():fail('Falta manifiesto de respaldo')
    rows=json.loads(mf.read_text(encoding='utf8'))
    if len(rows)!=10 or set(x['path'] for x in rows)!=set(files):fail('Respaldo de otra entrega')
    restore=[]
    for row in rows:
        p=get(row['path'],not row['created'])
        actual=p.read_bytes() if p.exists() else None
        if row['created']:
            if actual is not None and sha(actual)!=row['new_sha']:fail('Archivo nuevo modificado externamente: '+row['path'])
            restore.append((p,None,row['mode'],actual is not None))
        else:
            old=(backup/row['backup']).read_bytes()
            if sha(old)!=row['old_sha']:fail('Respaldo modificado externamente')
            if actual is None or sha(actual) not in (row['old_sha'],row['new_sha']):fail('Cambios posteriores: '+row['path'])
            restore.append((p,old,row['mode'],sha(actual)==row['new_sha']))
    for p,old,mode,needed in restore:
        if not needed:continue
        if old is None:p.unlink()
        else:replace(p,old,mode)
    print('OK: restauracion comprobada. Centralita, grabaciones y BD intactas.')
    sys.exit(0)
if len(sys.argv)!=2:fail('Argumentos adicionales')
plan=[]
for x in SPEC['changes']:
    p=get(x['path']);original=p.read_bytes()
    if b'\r\n' in original and original.count(b'\r\n')!=original.count(b'\n'):
        fail('Saltos de linea mixtos: '+x['path'])
    try:source=original.decode('utf8').replace('\r\n','\n')
    except UnicodeDecodeError:fail('Archivo no UTF-8: '+x['path'])
    crlf=b'\r\n' in original
    # La variante Hostinger se acepta únicamente si coincide su SHA256 exacto.
    # No se sustituyen a ciegas rutas, transferencias ni otras personalizaciones.
    variant=SPEC.get('hostingerVariants',{}).get(x['path'])
    patches=x['patches']
    if variant:
        fingerprint=sha(original)
        if fingerprint==variant['source_sha']:
            patches=variant['patches']
            print('VARIANTE HOSTINGER RECONOCIDA: '+x['path'])
        elif fingerprint==variant['updated_sha']:
            plan.append(dict(path=x['path'],file=p,old=original,target=original,
                mode=stat.S_IMODE(p.stat().st_mode),created=False,state='actualizado'))
            continue
    updated=source;pending=0;already=0
    for o,z in patches:
        o=(o+'\n' if o.endswith('\r') else o).replace('\r\n','\n')
        z=(z+'\n' if z.endswith('\r') else z).replace('\r\n','\n')
        # El fragmento nuevo puede conservar el texto anterior como subcadena.
        # Evaluar el estado intermedio para parches independientes del mismo archivo.
        if updated.count(z)==1:already+=1
        elif updated.count(o)==1:
            updated=updated.replace(o,z,1);pending+=1
        else:fail('Personalizacion desconocida o duplicada: '+x['path'])
    if pending and already:fail('Publicacion parcial del archivo: '+x['path'])
    target=(updated.replace('\n','\r\n') if crlf else updated).encode('utf8')
    if pending:lint(x['path'],target)
    plan.append(dict(path=x['path'],file=p,old=original,target=target,
         mode=stat.S_IMODE(p.stat().st_mode),created=False,state='pendiente' if pending else 'actualizado'))
n=SPEC['newFile'];p=get(n['path'],False);target=n['content'].encode('utf8')
original=p.read_bytes() if p.exists() else None
if original is not None and original!=target:fail('Endpoint nuevo diferente: '+n['path'])
if original is None:lint(n['path'],target)
plan.append(dict(path=n['path'],file=p,old=original,target=target,
    mode=stat.S_IMODE(p.stat().st_mode) if p.exists() else 0o644,
    created=not p.exists(),state='pendiente' if original is None else 'actualizado'))
for item in plan:print(item['path']+': '+item['state'])
count=sum(x['state']=='pendiente' for x in plan)
print('Archivos a modificar:',count)
if action=='--check':
    print('OK: comprobacion sin modificar archivos.')
    sys.exit(0)
if not count:
    print('OK: notificaciones ya actualizadas.')
    sys.exit(0)
# Ante una publicacion parcial detenerse en vez de mezclar contratos de JS/PHP.
if count!=len(plan):fail('Instalacion parcial: revisar archivos antes de aplicar')
backups.mkdir(parents=True,exist_ok=True,mode=0o700)
os.chmod(str(backups),0o700)
folder=Path(tempfile.mkdtemp(prefix='telefonia-notificaciones-',dir=str(backups)))
os.chmod(str(folder),0o700)
manifest=[]
for i,item in enumerate(plan):
    name='%02d.bak'%i
    if item['old'] is not None:
        backup=folder/name;backup.write_bytes(item['old']);os.chmod(str(backup),0o600)
    manifest.append(dict(path=item['path'],backup=name,created=item['created'],mode=item['mode'],
        old_sha=sha(item['old']) if item['old'] is not None else '',new_sha=sha(item['target'])))
file=folder/'manifest.json'
file.write_text(json.dumps(manifest,indent=2),encoding='utf8');os.chmod(str(file),0o600)
committed=[]
try:
    for item in plan:
        if item['state']!='pendiente':continue
        current=item['file'].read_bytes() if item['file'].exists() else None
        if current!=item['old']:fail('Archivo modificado simultaneamente: '+item['path'])
        replace(item['file'],item['target'],item['mode']);committed.append(item)
except BaseException:
    for item in reversed(committed):
        current=item['file'].read_bytes() if item['file'].exists() else None
        if current is None or sha(current)!=sha(item['target']):continue
        if item['old'] is None:item['file'].unlink()
        else:replace(item['file'],item['old'],item['mode'])
    raise
print('OK: notificaciones unificadas publicadas. Respaldo:',str(folder))
print('Sin modificaciones de llamadas, extensiones, webhooks, grabaciones o BD.')
